"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { CircleAlert, CircleCheck, Info, Megaphone, TriangleAlert, X } from "@/components/ui/icons";

// Banner: generated by UIX from the design system. Same variants and sizes as the Figma component.

const bannerVariants = cva(
  "flex w-full items-center gap-3 px-4 py-[10px] text-label-medium",
  {
    variants: {
      type: {
        brand: "skin-solid bg-brand text-fg-on-brand [&_[data-slot=icon]]:text-fg-on-brand [&_[data-slot=action]]:text-fg-on-brand [&_[data-slot=close]]:text-fg-on-brand",
        info: "skin-keep bg-info-subtle text-fg-primary [&_[data-slot=icon]]:text-icon-brand [&_[data-slot=action]]:text-fg-brand [&_[data-slot=close]]:text-icon-secondary",
        success: "skin-keep bg-success-subtle text-fg-primary [&_[data-slot=icon]]:text-icon-success [&_[data-slot=action]]:text-fg-brand [&_[data-slot=close]]:text-icon-secondary",
        warning: "skin-keep bg-warning-subtle text-fg-primary [&_[data-slot=icon]]:text-icon-warning [&_[data-slot=action]]:text-fg-brand [&_[data-slot=close]]:text-icon-secondary",
        error: "skin-keep bg-danger-subtle text-fg-primary [&_[data-slot=icon]]:text-icon-danger [&_[data-slot=action]]:text-fg-brand [&_[data-slot=close]]:text-icon-secondary",
      },
    },
    defaultVariants: {
      type: "brand",
    },
  },
);

const bannerIcons = { brand: Megaphone, info: Info, success: CircleCheck, warning: TriangleAlert, error: CircleAlert };

export interface BannerProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof bannerVariants> {
  /** Link or text shown after the message, underlined. */
  action?: React.ReactNode;
  /** Shows a close button and calls this when it is pressed. */
  onClose?: () => void;
}

const Banner = React.forwardRef<HTMLDivElement, BannerProps>(
  ({ className, type, action, onClose, children, ...props }, ref) => {
    const Icon = bannerIcons[type ?? "brand"];
    return (
      <div data-slot="banner" data-kind="surface" ref={ref} role="status" className={cn(bannerVariants({ type }), className)} {...props}>
        <Icon data-slot="icon" aria-hidden className="size-[18px] shrink-0" />
        <div className="min-w-0 flex-1">{children}</div>
        {action ? (
          <span data-slot="action" className="underline underline-offset-4">
            {action}
          </span>
        ) : null}
        {onClose ? (
          <button type="button" aria-label="Close" data-slot="close" onClick={onClose} className="shrink-0 cursor-pointer rounded-xs focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus">
            <X aria-hidden className="size-4" />
          </button>
        ) : null}
      </div>
    );
  },
);
Banner.displayName = "Banner";

export { Banner, bannerVariants };
